/*
 * Weak placeholders for the owner-verified-root material.
 *
 * The kernel needs three symbols to authenticate a window: the signed manifest
 * envelope, its length, and the 395-byte trusted key. They are generated by
 * scripts/make-root-policies.py from the exact byte stream the driver exposes.
 * Until that material is linked in (a strong definition replaces these weak
 * ones), kebab_verified_root_configured() reports false and the driver keeps
 * the bring-up behaviour that a boot argument selects.
 */
#include <stdint.h>

__attribute__((weak)) const uint8_t verified_root_manifest[1] = { 0 };
__attribute__((weak)) const uint64_t verified_root_manifest_bytes = 0;
__attribute__((weak)) const uint8_t verified_root_key[395] = { 0 };

int
kebab_verified_root_configured(void)
{
	extern const uint64_t verified_root_manifest_bytes;
	return verified_root_manifest_bytes != 0;
}
